for b in d['bands']:
    if 235<=b['band_cm1']<=246 or 280<=b['band_cm1']<=300 or 325<=b['band_cm1']<=360 or 425<=b['band_cm1']<=470 or 515<=b['band_cm1']<=535 or 575<=b['band_cm1']<=600:
        print('band', b['band_cm1'])
        for p in b['per_spectrum']:
            if p['present']:
                print(f\"   {p['label']}: pos {p['position_cm1']:.2f}±{p['position_err_cm1']:.2f} fwhm {p['fwhm_cm1']:.2f} h {p['height']:.3f} rel {p['height_rel_strongest']:.3f} shift {p.get('shift_vs_first_cm1','')}\")
            else:
                print(f\"   {p['label']}: absent\")
for k in d:
    if k not in ('bands',):
        print(k, json.dumps(d[k])[:1500])
"

